 VALUES('batch-create.items','batch-create','unit','items',200,200) ON CONFLICT(rule_key) DO NOTHING;
CREATE OR REPLACE FUNCTION public.check_ticket_batch_cash_unit_internal(p_occasion bigint)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.check_occasion_writable(p_occasion);
 IF EXISTS(SELECT 1 FROM eshop.external_services s JOIN public.occasions o ON o.unit=s.unit WHERE o.id=p_occasion AND s.type='FAKTUROID') THEN
  RAISE EXCEPTION 'CASH_SALE_INVOICE_WORKFLOW_REQUIRED'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.check_ticket_batch_cash_unit_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.check_ticket_batch_eligible_internal(p_form bigint)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE f public.forms; o public.occasions; feature jsonb; template jsonb;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form;
 SELECT * INTO STRICT o FROM public.occasions WHERE id=f.occasion;
 PERFORM public.check_ticket_batch_cash_unit_internal(o.id);
 -- Personal registration products and automatic participant imports are outside v1.
 IF EXISTS(SELECT 1 FROM public.form_fields WHERE form=f.id AND is_ticket_field AND is_required
   AND NOT is_hidden AND type NOT IN ('product_type','spot','ticket','html')) THEN
  RAISE EXCEPTION 'BATCH_PERSONAL_REGISTRATION_UNSUPPORTED'; END IF;
 SELECT value INTO feature FROM jsonb_array_elements(o.features) WHERE value->>'code'='ticket';
 IF feature IS NULL OR coalesce((feature->>'is_enabled')::boolean,false) IS NOT TRUE THEN
  RAISE EXCEPTION 'BATCH_TICKET_FEATURE_REQUIRED'; END IF;
 PERFORM public.validate_ticket_layout(feature->'layout');
 PERFORM public.validate_ticket_layout_references(o.id,feature->'layout');
 -- Explicit saved templates make anonymity and the frozen render contract reviewable.
 template:=feature#>ARRAY['layout','templates',CASE WHEN feature->>'ticket_type'='named' THEN 'named' ELSE 'wide' END];
 IF template IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(template->'elements') e
 WHERE e->>'binding'='orderName' AND (e->>'visible')::boolean) THEN
  RAISE EXCEPTION 'BATCH_ANONYMOUS_TEMPLATE_REQUIRED'; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.normalize_ticket_batch_selection_internal(p_form bigint,p_selection jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 IF jsonb_typeof(p_selection) IS DISTINCT FROM 'array' OR jsonb_array_length(p_selection) NOT BETWEEN 1 AND 200
 OR octet_length(p_selection::text)>1048576 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_selection) t
 WHERE jsonb_typeof(t)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(t) k WHERE k NOT IN ('spot','fields'))) THEN
  RAISE invalid_parameter_value USING MESSAGE='BATCH_SELECTION_INVALID'; END IF;
 result:=public.normalize_form_ticket_answers_internal(p_form,p_selection);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result) t CROSS JOIN LATERAL jsonb_array_elements(coalesce(t->'fields','[]')) f
  WHERE NOT f ? 'product_type' OR EXISTS(SELECT 1 FROM jsonb_object_keys(f) k
    WHERE k NOT IN ('product_type','_subFieldId','currency_code') AND k !~ '^[0-9]+$')) THEN
  RAISE invalid_parameter_value USING MESSAGE='BATCH_SELECTION_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result) t JOIN eshop.spots s ON s.id=(t->>'spot')::bigint
  JOIN public.forms f ON f.id=p_form WHERE s.blueprint IS DISTINCT FROM f.blueprint OR s.occasion IS DISTINCT FROM f.occasion) THEN
  RAISE EXCEPTION 'BATCH_SPOT_SCOPE_MISMATCH'; END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.check_ticket_batch_eligible_internal(bigint),
 public.normalize_ticket_batch_selection_internal(bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
-- Read preview and write command share the same normalized, server-priced selection.
CREATE OR REPLACE FUNCTION public.ticket_batch_selection_summary_internal(p_form bigint,p_selection jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE fid bigint; oc bigint; invalid boolean; currency text; total numeric; item record; capacity jsonb;
BEGIN
 SELECT occasion INTO STRICT oc FROM public.forms WHERE id=p_form;
 IF (SELECT count(*) FROM jsonb_array_elements(p_selection) t WHERE t->>'spot' IS NOT NULL)<>
  (SELECT count(DISTINCT t->>'spot') FROM jsonb_array_elements(p_selection) t WHERE t->>'spot' IS NOT NULL) THEN
  RAISE EXCEPTION 'BATCH_DUPLICATE_SPOT'; END IF;
 FOR item IN
  WITH choices AS (
   SELECT n,(a->>'product_type')::bigint product,false seated FROM jsonb_array_elements(p_selection) WITH ORDINALITY t(v,n)
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(v->'fields','[]')) a
   UNION ALL SELECT n,s.product,true FROM jsonb_array_elements(p_selection) WITH ORDINALITY t(v,n)
    LEFT JOIN eshop.spots s ON s.id=(v->>'spot')::bigint WHERE v->>'spot' IS NOT NULL)
  SELECT c.*,p.price,p.currency_code,p.maximum,p.is_hidden,p.occasion,pt.type,pt.occasion type_occasion,p.product_type,
   EXISTS(SELECT 1 FROM public.form_fields ff WHERE ff.form=p_form AND ff.product_type=p.product_type AND NOT ff.is_hidden) offered,
   (SELECT count(*) FROM eshop.order_product_ticket x WHERE x.product=p.id) occupied,
   count(*) OVER(PARTITION BY c.product) selected
  FROM choices c LEFT JOIN eshop.products p ON p.id=c.product LEFT JOIN eshop.product_types pt ON pt.id=p.product_type
 LOOP
  IF item.occasion IS DISTINCT FROM oc OR item.type_occasion IS DISTINCT FROM oc OR item.is_hidden
   OR item.price IS NULL OR item.price<0 OR (NOT item.seated AND NOT item.offered) THEN RAISE EXCEPTION 'BATCH_PRODUCT_UNAVAILABLE'; END IF;
  IF item.maximum>0 AND item.occupied+item.selected>item.maximum THEN RAISE EXCEPTION 'PRODUCT_CAPACITY_EXCEEDED'; END IF;
  IF currency IS NULL THEN currency:=item.currency_code;
  ELSIF currency IS DISTINCT FROM item.currency_code THEN RAISE EXCEPTION 'BATCH_CURRENCY_MISMATCH'; END IF;
  total:=coalesce(total,0)+item.price;
 END LOOP;
 IF total IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_selection) t WHERE t->>'spot' IS NULL AND NOT EXISTS(
  SELECT 1 FROM jsonb_array_elements(coalesce(t->'fields','[]')) a JOIN eshop.products p ON p.id=(a->>'product_type')::bigint
  JOIN eshop.product_types pt ON pt.id=p.product_type WHERE pt.type='spot')) THEN RAISE EXCEPTION 'BATCH_ADMISSION_PRODUCT_REQUIRED'; END IF;
 capacity:=public.get_form_capacity_snapshot_internal(p_form);
 IF (capacity->>'enabled')::boolean AND jsonb_array_length(p_selection)>(capacity->>'remainingPublic')::bigint THEN RAISE EXCEPTION 'FORM_CAPACITY_EXCEEDED'; END IF;
 RETURN jsonb_build_object('count',jsonb_array_length(p_selection),'prices',jsonb_build_array(jsonb_build_object('currency_code',currency,'amount',total)),'capacity',capacity);
END $$;
REVOKE ALL ON FUNCTION public.ticket_batch_selection_summary_internal(bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop_ticket_batches/reads.sql
CREATE OR REPLACE FUNCTION public.get_ticket_batch_detail(p_batch uuid,p_after integer DEFAULT 0)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.ticket_batches; can_edit boolean; can_sell boolean;
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch;
 IF auth.uid() IS NULL OR public.get_is_editor_order_view_on_occasion(b.occasion) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order viewer required'; END IF;
 can_edit:=public.get_is_editor_order_on_occasion(b.occasion);
 can_sell:=can_edit AND public.get_is_manager_on_unit((SELECT unit FROM public.occasions WHERE id=b.occasion))
  AND NOT EXISTS(SELECT 1 FROM eshop.external_services s JOIN public.occasions o ON o.unit=s.unit WHERE o.id=b.occasion AND s.type='FAKTUROID')
  AND b.manifest_hash IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready');
 RETURN jsonb_build_object('id',b.id,'occasion',b.occasion,'form',b.form,'title',b.title,'stockOrderId',b.stock_order_id,
 'currency',b.currency_code,'createdAt',b.created_at,'manifestHash',b.manifest_hash,
 'counts',(SELECT jsonb_build_object('total',count(*),'available',count(*) FILTER(WHERE i.sale_order_id IS NULL AND t.state<>'storno'),
 'soldActive',count(*) FILTER(WHERE i.sale_order_id IS NOT NULL AND t.state<>'storno'),
 'voidedUnsold',count(*) FILTER(WHERE i.sale_order_id IS NULL AND t.state='storno'),
 'cancelledAfterSale',count(*) FILTER(WHERE i.sale_order_id IS NOT NULL AND t.state='storno'))
 FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id WHERE i.batch_id=b.id),
 'stockValue',(SELECT coalesce(sum((p->>'price')::numeric),0) FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id
 CROSS JOIN LATERAL jsonb_array_elements(b.snapshot->'tickets') st CROSS JOIN LATERAL jsonb_array_elements(st->'products') p
 WHERE i.batch_id=b.id AND i.sale_order_id IS NULL AND t.state<>'storno' AND (st->>'id')::bigint=t.id),
 'receivedAmount',(SELECT coalesce(sum(coalesce(pi.paid,0)-coalesce(pi.returned,0)),0) FROM eshop.payment_info pi JOIN eshop.orders o ON o.payment_info=pi.id
 WHERE o.id IN(SELECT sale_order_id FROM eshop.ticket_batch_items WHERE batch_id=b.id)),
 'sales',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'symbol',o.order_symbol,'createdAt',o.created_at,'amount',o.price) ORDER BY o.created_at DESC),'[]')
 FROM (SELECT * FROM eshop.orders WHERE id IN(SELECT sale_order_id FROM eshop.ticket_batch_items WHERE batch_id=b.id) ORDER BY created_at DESC,id LIMIT 20) o),
 'allowedActions',jsonb_build_array('view','download')||CASE WHEN can_edit THEN jsonb_build_array('void','prepare') ELSE '[]' END
  ||CASE WHEN can_sell THEN jsonb_build_array('sell') ELSE '[]' END,
 'items',(SELECT coalesce(jsonb_agg(to_jsonb(row) ORDER BY ordinal),'[]') FROM (
 SELECT i.ordinal,t.id,t.ticket_symbol,t.state,i.sale_order_id,
 (SELECT value FROM jsonb_array_elements(b.snapshot->'tickets') WHERE (value->>'id')::bigint=t.id) snapshot
 FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id WHERE i.batch_id=b.id AND i.ordinal>greatest(0,p_after)
 ORDER BY i.ordinal LIMIT 50) row),
 'documents',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'key',part_key,'kind',kind,'state',state,
 'bytes',byte_count,'pages',page_count,'errorCode',error_code) ORDER BY part_key),'[]') FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id));
END $$;
CREATE OR REPLACE FUNCTION public.get_ticket_batches(p_occasion bigint,p_before timestamptz DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR public.get_is_editor_order_view_on_occasion(p_occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 RETURN (SELECT coalesce(jsonb_agg(public.get_ticket_batch_detail(id) ORDER BY created_at DESC,id),'[]') FROM (
  SELECT id,created_at FROM eshop.ticket_batches WHERE occasion=p_occasion AND (p_before IS NULL OR created_at<p_before)
  ORDER BY created_at DESC,id LIMIT 20) b);
END $$;
CREATE OR REPLACE FUNCTION public.preview_ticket_batch(p_form bigint,p_selection jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE f public.forms; normalized jsonb; prices jsonb;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form;
 IF auth.uid() IS NULL OR public.get_is_editor_order_on_occasion(f.occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 PERFORM public.check_ticket_batch_eligible_internal(f.id);
 normalized:=public.normalize_ticket_batch_selection_internal(f.id,p_selection);
 RETURN public.ticket_batch_selection_summary_internal(f.id,normalized)||jsonb_build_object('selection',normalized);
END $$;
REVOKE ALL ON FUNCTION public.get_ticket_batch_detail(uuid,integer),public.get_ticket_batches(bigint,timestamptz),
 public.preview_ticket_batch(bigint,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_ticket_batch_detail(uuid,integer),public.get_ticket_batches(bigint,timestamptz),
 public.preview_ticket_batch(bigint,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_ticket_batch_create_options(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR public.get_is_editor_order_on_occasion(p_occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'title',f.title,'blueprint',f.blueprint,'products',
  (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'price',p.price,'currency',p.currency_code) ORDER BY p.id),'[]')
   FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type WHERE p.occasion=p_occasion AND pt.type='spot' AND NOT p.is_hidden
   AND EXISTS(SELECT 1 FROM public.form_fields ff WHERE ff.form=f.id AND ff.product_type=p.product_type AND NOT ff.is_hidden))) ORDER BY f.id),'[]')
 FROM public.forms f WHERE f.occasion=p_occasion);
END $$;
REVOKE ALL ON FUNCTION public.get_ticket_batch_create_options(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_ticket_batch_create_options(bigint) TO authenticated;

-- Source: database/functions/eshop_ticket_batches/create.sql
-- Private until immutable documents and the complete UI are available.
CREATE OR REPLACE FUNCTION public.create_ticket_batch_client_sync_v1(
 p_form bigint,p_title text,p_selection jsonb,p_secret uuid,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE f public.forms; o public.occasions; claimed jsonb; selection jsonb; oid bigint; tid bigint; symbol text;
 item jsonb; products jsonb; tickets jsonb:='[]'; currency text; result jsonb; bid uuid; ordinal integer:=0; snap jsonb;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form;
 IF auth.uid() IS NULL OR public.get_is_editor_order_on_occasion(f.occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 IF length(trim(p_title)) NOT BETWEEN 1 AND 200 OR p_title IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='BATCH_TITLE_INVALID'; END IF;
 selection:=public.normalize_ticket_batch_selection_internal(f.id,p_selection);
 claimed:=public.begin_client_mutation_v1(p_command_id,'inventory.ticket_batch.create',f.occasion,auth.uid(),
  encode(extensions.digest(jsonb_build_object('form',f.id,'title',p_title,'selection',selection,'secret',p_secret)::text,'sha256'),'hex'));
 IF claimed->>'disposition'='replay' THEN RETURN claimed->'response'; END IF;
 BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form FOR UPDATE;
 SELECT * INTO STRICT o FROM public.occasions WHERE id=f.occasion;
 PERFORM public.check_ticket_batch_eligible_internal(f.id);
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('batch-create',o.unit,o.organization),
 jsonb_build_object('actor',auth.uid(),'unit',o.unit,'organization',o.organization),jsonb_build_object('batch-create.items',jsonb_array_length(selection)));
 IF f.participant_capacity IS NOT NULL AND jsonb_array_length(selection)>(public.get_form_capacity_snapshot_internal(f.id)->>'remainingPublic')::bigint THEN
  RAISE EXCEPTION 'FORM_CAPACITY_EXCEEDED'; END IF;
 oid:=public.allocate_ticket_order_identity_internal(f.id);
 PERFORM public.lock_ticket_order_products_internal(oid,jsonb_build_object('ticket',selection));
 PERFORM public.ticket_batch_selection_summary_internal(f.id,selection);
 PERFORM public.hold_ticket_batch_spots_internal(f.id,ARRAY(SELECT (t->>'spot')::bigint FROM jsonb_array_elements(selection) t WHERE t->>'spot' IS NOT NULL ORDER BY (t->>'spot')::bigint),p_secret);
 FOR item IN SELECT value FROM jsonb_array_elements(selection) LOOP
  IF item->>'spot' IS NOT NULL THEN
   PERFORM 1 FROM eshop.spots WHERE id=(item->>'spot')::bigint AND blueprint=f.blueprint AND occasion=f.occasion
    AND secret=p_secret AND secret_expiration_time>clock_timestamp() AND order_product_ticket IS NULL FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'BATCH_SPOT_HOLD_REQUIRED'; END IF;
  END IF;
  symbol:=public.generate_ticket_symbol(o.organization,o.id);
  INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(o.id,'ordered',symbol) RETURNING id INTO tid;
  products:=public.materialize_ticket_products_internal_v1(oid,f.id,tid,item,p_secret);
  IF currency IS NULL THEN currency:=products->>'currency_code';
  ELSIF currency IS DISTINCT FROM products->>'currency_code' THEN RAISE EXCEPTION 'BATCH_CURRENCY_MISMATCH'; END IF;
  tickets:=tickets||jsonb_build_object('id',tid,'ticket_symbol',symbol,'products',products->'products');
 END LOOP;
 PERFORM public.apply_allocations(oid);
 tickets:=public.order_tickets_with_seating_internal(oid,tickets);
 UPDATE eshop.orders SET state='stock',price=NULL,payment_info=NULL,currency_code=currency,data=jsonb_build_object('tickets',tickets),updated_at=clock_timestamp() WHERE id=oid;
 SELECT jsonb_build_object('occasion',to_jsonb(o),'catalog',public.get_products_and_types(o.id)::jsonb,
 'tickets',tickets,'documentData',(SELECT jsonb_agg(jsonb_set(d,'{ticket,price_decimal_digits}',to_jsonb(CASE WHEN (d#>>'{ticket,price}')::numeric=trunc((d#>>'{ticket,price}')::numeric) THEN 0 ELSE 2 END),true) ORDER BY (x->>'id')::bigint)
 FROM jsonb_array_elements(tickets) x CROSS JOIN LATERAL (SELECT public.get_ticket_details_for_generating((x->>'id')::bigint) d) frozen),'renderContractVersion',1) INTO snap;
 INSERT INTO eshop.ticket_batches(occasion,form,stock_order_id,title,created_by,currency_code,snapshot)
 VALUES(o.id,f.id,oid,trim(p_title),auth.uid(),currency,snap) RETURNING id INTO bid;
 INSERT INTO eshop.ticket_batch_items(batch_id,ticket_id,ordinal)
 SELECT bid,(value->>'id')::bigint,n FROM jsonb_array_elements(tickets) WITH ORDINALITY x(value,n);
 UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=f.id;
 INSERT INTO eshop.orders_history("order",state,data,currency_code) VALUES(oid,'stock',jsonb_build_object('batchId',bid),currency);
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,o.id,'inventory.ticket_batch.create',
 jsonb_build_array(jsonb_build_object('entityType','order','entityId',oid,'operation','insert','safeLabel','Ticket batch',
 'changedFields',jsonb_build_array('tickets','allocations'))),ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=o.id AND is_editor_order_view),
 jsonb_build_object('batchId',bid,'stockOrderId',oid,'count',jsonb_array_length(selection)));
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM=ANY(ARRAY['FORM_CAPACITY_EXCEEDED','PRODUCT_CAPACITY_EXCEEDED','BATCH_SPOT_UNAVAILABLE','BATCH_SPOT_HOLD_REQUIRED','BATCH_CURRENCY_MISMATCH','BATCH_PRODUCT_UNAVAILABLE','BATCH_ADMISSION_PRODUCT_REQUIRED','CASH_SALE_INVOICE_WORKFLOW_REQUIRED','BATCH_ANONYMOUS_TEMPLATE_REQUIRED','BATCH_PERSONAL_REGISTRATION_UNSUPPORTED']) THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('errorCode',SQLERRM));
  END IF;
  RAISE;
 END;
END $$;
REVOKE ALL ON FUNCTION public.create_ticket_batch_client_sync_v1(bigint,text,jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop_ticket_batches/sales.sql
-- A sale moves existing OPT parents. It never allocates inventory or generates QR.
CREATE OR REPLACE FUNCTION public.sell_ticket_batch_items_client_sync_v1(
 p_batch uuid,p_tickets bigint[],p_contact jsonb,p_send_tickets boolean,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.ticket_batches; occ public.occasions; claimed jsonb; oid bigint; pi bigint; tx bigint;
 v_amount numeric; tickets jsonb; sale_data jsonb; ids bigint[]; email text;
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch;
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=b.occasion;
 IF auth.uid() IS NULL OR public.get_is_editor_order_on_occasion(b.occasion) IS NOT TRUE
 OR public.get_is_manager_on_unit(occ.unit) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 ids:=ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id ORDER BY id);
 IF cardinality(ids) NOT BETWEEN 1 AND 20 OR array_position(ids,NULL) IS NOT NULL
 OR cardinality(ids) IS NULL OR p_send_tickets IS NULL
 OR jsonb_typeof(coalesce(p_contact,'{}'))<>'object' OR octet_length(coalesce(p_contact,'{}')::text)>8192
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(coalesce(p_contact,'{}')) k WHERE k NOT IN ('email','name','surname','phone')) THEN
  RAISE invalid_parameter_value USING MESSAGE='BATCH_SALE_SELECTION_INVALID'; END IF;
 sale_data:=jsonb_strip_nulls(coalesce(p_contact,'{}'));
 email:=nullif(trim(sale_data->>'email'),'');
 IF email IS NULL THEN sale_data:=sale_data-'email';
 ELSIF email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'BATCH_CONTACT_INVALID';
 ELSE sale_data:=jsonb_set(sale_data,'{email}',to_jsonb(email)); END IF;
 IF p_send_tickets AND email IS NULL THEN RAISE EXCEPTION 'BATCH_DELIVERY_EMAIL_REQUIRED'; END IF;
 claimed:=public.begin_client_mutation_v1(p_command_id,'inventory.ticket_batch.sell',b.occasion,auth.uid(),
 encode(extensions.digest(jsonb_build_object('batch',b.id,'tickets',ids,'contact',sale_data,'sendTickets',p_send_tickets)::text,'sha256'),'hex'));
 IF claimed->>'disposition'='replay' THEN RETURN claimed->'response'; END IF;
 BEGIN
 PERFORM public.check_ticket_batch_cash_unit_internal(b.occasion);
 PERFORM public.admit_order_mutation_v1(b.occasion,cardinality(ids));
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[b.stock_order_id]);
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch FOR UPDATE;
 IF b.manifest_hash IS NULL OR NOT EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND kind='print')
 OR EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready') THEN
  RAISE EXCEPTION 'BATCH_PRINT_NOT_READY'; END IF;
 PERFORM 1 FROM eshop.tickets WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 IF (SELECT count(*) FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id
  WHERE i.batch_id=b.id AND t.id=ANY(ids) AND i.sale_order_id IS NULL AND t.state='ordered'
  AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=t.id AND x."order"=b.stock_order_id)
  AND NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=t.id AND x."order"<>b.stock_order_id))<>cardinality(ids) THEN
  RAISE EXCEPTION 'ITEM_NOT_IN_STOCK'; END IF;
 SELECT jsonb_agg(t ORDER BY (t->>'id')::bigint) INTO tickets FROM jsonb_array_elements(b.snapshot->'tickets') t WHERE (t->>'id')::bigint=ANY(ids);
 SELECT sum((p->>'price')::numeric) INTO v_amount FROM jsonb_array_elements(tickets) t CROSS JOIN LATERAL jsonb_array_elements(t->'products') p;
 IF v_amount IS NULL OR v_amount<0 THEN RAISE EXCEPTION 'BATCH_SNAPSHOT_INVALID'; END IF;
 oid:=public.allocate_ticket_order_identity_internal(b.form);
 INSERT INTO eshop.payment_info(amount,currency_code,payment_method) VALUES(v_amount,b.currency_code,'bank') RETURNING id INTO pi;
 sale_data:=sale_data||jsonb_build_object('tickets',tickets,'ticketBatchOrigin',jsonb_build_object('batchId',b.id,'sendTickets',p_send_tickets));
 UPDATE eshop.orders SET price=v_amount,currency_code=b.currency_code,payment_info=pi,data=sale_data,updated_at=clock_timestamp() WHERE id=oid;
 UPDATE eshop.order_product_ticket SET "order"=oid WHERE ticket=ANY(ids) AND "order"=b.stock_order_id;
 UPDATE eshop.ticket_batch_items SET sale_order_id=oid WHERE batch_id=b.id AND ticket_id=ANY(ids) AND sale_order_id IS NULL;
 UPDATE eshop.orders stock SET data=jsonb_set(stock.data,'{tickets}',coalesce((SELECT jsonb_agg(t) FROM jsonb_array_elements(stock.data->'tickets') t
  WHERE NOT (t->>'id')::bigint=ANY(ids)),'[]')),updated_at=clock_timestamp() WHERE id=b.stock_order_id;
 tx:=public.insert_manual_transaction_internal_v1(v_amount,b.currency_code,occ.unit,NULL,clock_timestamp(),'Ticket batch cash sale',pi);
 IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=oid AND state='paid')
 OR NOT EXISTS(SELECT 1 FROM eshop.transactions tr WHERE tr.id=tx AND tr.payment_info=pi AND tr.amount=v_amount) THEN
  RAISE EXCEPTION 'BATCH_PAYMENT_NOT_COMMITTED'; END IF;
 INSERT INTO eshop.orders_history("order",state,data,price,currency_code) VALUES
 (b.stock_order_id,'stock',jsonb_build_object('saleOrderId',oid,'ticketIds',ids),NULL,b.currency_code),
 (oid,'paid',jsonb_build_object('batchId',b.id,'transactionId',tx,'ticketIds',ids),v_amount,b.currency_code);
 UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=b.form;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,b.occasion,'inventory.ticket_batch.sell',
 jsonb_build_array(jsonb_build_object('entityType','order','entityId',b.stock_order_id,'operation','update','safeLabel','Ticket batch',
 'changedFields',jsonb_build_array('tickets','parent')),jsonb_build_object('entityType','order','entityId',oid,'operation','insert',
 'safeLabel','Cash sale','changedFields',jsonb_build_array('tickets','payment','parent'))),
 ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=b.occasion AND is_editor_order_view),
 jsonb_build_object('batchId',b.id,'orderId',oid,'transactionId',tx,'amount',v_amount,'currency',b.currency_code,'ticketIds',ids));
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM=ANY(ARRAY['ITEM_NOT_IN_STOCK','BATCH_PRINT_NOT_READY','CASH_SALE_INVOICE_WORKFLOW_REQUIRED']) THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('errorCode',SQLERRM));
  END IF;
  RAISE;
 END;
END $$;
CREATE OR REPLACE FUNCTION public.void_ticket_batch_items_client_sync_v1(p_batch uuid,p_tickets bigint[],p_reason text,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.ticket_batches; ids bigint[]; claimed jsonb;
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch;
 IF auth.uid() IS NULL OR public.get_is_editor_order_on_occasion(b.occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 ids:=ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id ORDER BY id);
 IF cardinality(ids) NOT BETWEEN 1 AND 200 OR cardinality(ids) IS NULL OR length(trim(p_reason)) NOT BETWEEN 1 AND 500 OR p_reason IS NULL THEN
  RAISE invalid_parameter_value USING MESSAGE='BATCH_VOID_SELECTION_INVALID'; END IF;
 claimed:=public.begin_client_mutation_v1(p_command_id,'inventory.ticket_batch.void',b.occasion,auth.uid(),
 encode(extensions.digest(jsonb_build_object('batch',b.id,'tickets',ids,'reason',p_reason)::text,'sha256'),'hex'));
 IF claimed->>'disposition'='replay' THEN RETURN claimed->'response'; END IF;
 BEGIN
 PERFORM public.admit_order_mutation_v1(b.occasion,cardinality(ids));
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[b.stock_order_id]);
 PERFORM 1 FROM eshop.ticket_batches WHERE id=b.id FOR UPDATE;
 PERFORM 1 FROM eshop.tickets WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 IF (SELECT count(*) FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id
  WHERE i.batch_id=b.id AND t.id=ANY(ids) AND i.sale_order_id IS NULL AND t.state='ordered'
  AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=t.id AND x."order"=b.stock_order_id))<>cardinality(ids) THEN
  RAISE EXCEPTION 'ITEM_NOT_IN_STOCK'; END IF;
 PERFORM public.internal_storno_tickets_221(ids);
 INSERT INTO eshop.orders_history("order",state,data,currency_code)
 VALUES(b.stock_order_id,'stock',jsonb_build_object('voidedTicketIds',ids,'reason',p_reason),b.currency_code);
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,b.occasion,'inventory.ticket_batch.void',
 jsonb_build_array(jsonb_build_object('entityType','order','entityId',b.stock_order_id,'operation','update','safeLabel','Ticket batch',
 'changedFields',jsonb_build_array('tickets','allocations'))),ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=b.occasion AND is_editor_order_view),
 jsonb_build_object('batchId',b.id,'ticketIds',ids));
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM='ITEM_NOT_IN_STOCK' THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('errorCode',SQLERRM));
  END IF;
  RAISE;
 END;
END $$;
REVOKE ALL ON FUNCTION public.sell_ticket_batch_items_client_sync_v1(uuid,bigint[],jsonb,boolean,uuid),
 public.void_ticket_batch_items_client_sync_v1(uuid,bigint[],text,uuid) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop/get_ticket_details_for_generating.sql
CREATE OR REPLACE FUNCTION public.get_ticket_details_for_generating(ticket_id_input BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        -- 1. Build the 'ticket' key
        'ticket', (
            SELECT to_jsonb(t_detail)
            FROM (
                SELECT
                    t.id,
                    (SELECT i.batch_id FROM eshop.ticket_batch_items i WHERE i.ticket_id=t.id) AS batch_id,
                    t.ticket_symbol,
                    t.occasion,
                    t.note,
                    t.state,
                    b.title AS table_title,
                    -- Subquery for Spot/Product details
                    (
                        SELECT jsonb_agg(ticket_prod ORDER BY ticket_prod.id)
                        FROM (
                            SELECT
                                opt2.id,
                                opt2.product,
                                s.title AS spot_title,
                                p.data->>'short_title' AS short_title,
                                p.title AS product_title, 
                                (
                                    SELECT g.value->>'title'
                                    FROM jsonb_array_elements(bp.groups) AS g(value)
                                    WHERE (g.value->>'id')::bigint = (
                                        SELECT (o2.value->>'group')::bigint
                                        FROM jsonb_array_elements(bp.objects) AS o2(value)
                                        WHERE (o2.value->>'id')::bigint = s.id
                                          AND o2.value->>'type' = 'spot'
                                        LIMIT 1
                                    )
                                    LIMIT 1
                                ) AS spot_group_title
                            FROM eshop.order_product_ticket opt2
                            LEFT JOIN eshop.spots s
                                ON s.order_product_ticket = opt2.id
                            LEFT JOIN eshop.products p
                                ON p.id = opt2.product
                            LEFT JOIN eshop.product_types pt 
                                ON pt.id = p.product_type
                            LEFT JOIN eshop.blueprints bp
                                ON bp.id = s.blueprint
                            WHERE opt2.ticket = t.id
                              AND NOT (pt.type = 'spot' AND s.title IS NULL)
                        ) ticket_prod
                    ) AS order_product_ticket,

                    -- Subquery for Price (extracting from ord.data)
                    (
                      SELECT COALESCE(SUM((prod->>'price')::numeric), 0)
                      FROM jsonb_array_elements(ord.data->'tickets') ticket_json,
                           jsonb_array_elements(ticket_json->'products') prod
                      WHERE (ticket_json->>'id')::bigint = t.id
                    ) AS price,

                    -- Subquery for Currency (extracting from ord.data)
                    (
                      SELECT (prod->>'currency_code')
                      FROM jsonb_array_elements(ord.data->'tickets') ticket_json,
                           jsonb_array_elements(ticket_json->'products') prod
                      WHERE (ticket_json->>'id')::bigint = t.id
                      LIMIT 1
                    ) AS currency_code
            ) t_detail
        ),

        -- 2. Build the 'occasion' key (dumps the whole occasion row including 'features')
        'occasion', to_jsonb(o)||jsonb_build_object('demo_read_only',public.is_demo_occasion(o.id)),
        'order_data', jsonb_build_object('name', ord.data->'name', 'surname', ord.data->'surname')
    )
    INTO result
    FROM eshop.tickets t
    -- Join Occasion to get the occasion object
    JOIN public.occasions o
        ON o.id = t.occasion
    -- Join Blueprint for the table title
    LEFT JOIN eshop.blueprints b
        ON b.occasion = o.id
    -- Join Order Tables to expose 'ord.data' for the ticket sub-calculations above
    LEFT JOIN eshop.order_product_ticket opt
        ON opt.ticket = t.id
    LEFT JOIN eshop.orders ord
        ON ord.id = opt."order"
    WHERE t.id = ticket_id_input AND t.state IS DISTINCT FROM 'waitlisted' AND t.ticket_symbol IS NOT NULL
      AND ord.state IS DISTINCT FROM 'waitlisted';

    RETURN result;
END;
$$;

-- Source: database/functions/eshop_ticket_batches/documents.sql
-- User claim authorizes the operation; only trusted renderer can attest stored bytes.
CREATE OR REPLACE FUNCTION public.claim_ticket_batch_document(p_batch uuid,p_part uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.ticket_batches; part eshop.ticket_batch_document_parts; token uuid:=extensions.gen_random_uuid();
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch FOR UPDATE;
 IF auth.uid() IS NULL OR public.get_is_editor_order_view_on_occasion(b.occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 PERFORM public.admit_ticket_batch_document_internal(b.occasion);
 IF b.manifest_hash IS NULL THEN
  IF b.resource_lease_expires_at>clock_timestamp() THEN RETURN jsonb_build_object('state','pending'); END IF;
  UPDATE eshop.ticket_batches SET resource_lease_token=token,resource_lease_actor=auth.uid(),
   resource_lease_expires_at=clock_timestamp()+interval '2 minutes',resource_error_code=NULL WHERE id=b.id;
  RETURN public.bound_document_data_v1(jsonb_build_object('state','claimed','kind','resources','lease',token,'snapshot',b.snapshot,'batchId',b.id));
 END IF;
 IF p_part IS NULL THEN
  SELECT * INTO part FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready'
   AND (lease_expires_at IS NULL OR lease_expires_at<=clock_timestamp()) ORDER BY kind,part_key LIMIT 1 FOR UPDATE;
 ELSE SELECT * INTO STRICT part FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND id=p_part FOR UPDATE;
 END IF;
 IF part.id IS NULL THEN RETURN jsonb_build_object('state',CASE WHEN EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready') THEN 'pending' ELSE 'ready' END); END IF;
 IF part.state='ready' THEN RETURN jsonb_build_object('state','ready','partId',part.id,'objectKey',part.object_key,'digest',part.content_digest); END IF;
 IF part.lease_expires_at>clock_timestamp() THEN RETURN jsonb_build_object('state','pending'); END IF;
 UPDATE eshop.ticket_batch_document_parts SET state='rendering',lease_token=token,lease_actor=auth.uid(),
 lease_expires_at=clock_timestamp()+interval '2 minutes',error_code=NULL WHERE id=part.id;
 RETURN public.bound_document_data_v1(jsonb_build_object('state','claimed','kind',part.kind,'lease',token,'partId',part.id,
 'ticketIds',part.ticket_ids,'batchId',b.id,'manifestHash',b.manifest_hash,'manifest',b.resource_manifest,
 'objectKey',b.id::text||'/'||b.manifest_hash||'/'||part.part_key||'.pdf'));
END $$;
CREATE OR REPLACE FUNCTION public.complete_ticket_batch_resources_internal(p_batch uuid,p_lease uuid,p_manifest jsonb,p_part_size integer)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.ticket_batches; hash text;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch FOR UPDATE;
 IF b.manifest_hash IS NOT NULL THEN RETURN b.manifest_hash; END IF;
 IF b.resource_lease_token IS DISTINCT FROM p_lease OR b.resource_lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'BATCH_STALE_LEASE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=b.occasion AND "user"=b.resource_lease_actor AND is_editor_order_view) THEN RAISE insufficient_privilege; END IF;
 IF jsonb_typeof(p_manifest) IS DISTINCT FROM 'object' OR octet_length(p_manifest::text)>4194304 OR p_part_size NOT BETWEEN 1 AND 20 THEN
  RAISE invalid_parameter_value; END IF;
 hash:=encode(extensions.digest(p_manifest::text,'sha256'),'hex');
 UPDATE eshop.ticket_batches SET resource_manifest=p_manifest,manifest_hash=hash,resource_lease_token=NULL,
 resource_lease_expires_at=NULL WHERE id=b.id;
 INSERT INTO eshop.ticket_batch_document_parts(batch_id,part_key,kind,ticket_ids,manifest_hash)
 SELECT b.id,'single-'||lpad(ordinal::text,3,'0'),'single',ARRAY[ticket_id],hash FROM eshop.ticket_batch_items WHERE batch_id=b.id;
 INSERT INTO eshop.ticket_batch_document_parts(batch_id,part_key,kind,ticket_ids,manifest_hash)
 SELECT b.id,'print-'||lpad(part::text,3,'0'),'print',array_agg(ticket_id ORDER BY ordinal),hash
 FROM (SELECT *,1+(ordinal-1)/p_part_size part FROM eshop.ticket_batch_items WHERE batch_id=b.id) i GROUP BY part;
 RETURN hash;
END $$;
CREATE OR REPLACE FUNCTION public.complete_ticket_batch_document_internal(p_part uuid,p_lease uuid,p_digest text,p_bytes bigint,p_pages integer)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.ticket_batches; part eshop.ticket_batch_document_parts;
BEGIN
 PERFORM public.require_service_role();
 SELECT b0.* INTO STRICT b FROM eshop.ticket_batches b0 JOIN eshop.ticket_batch_document_parts p ON p.batch_id=b0.id WHERE p.id=p_part FOR UPDATE OF b0;
 SELECT * INTO STRICT part FROM eshop.ticket_batch_document_parts WHERE id=p_part FOR UPDATE;
 IF part.state='ready' THEN
  IF part.content_digest IS DISTINCT FROM p_digest THEN RAISE EXCEPTION 'BATCH_DOCUMENT_IMMUTABLE'; END IF; RETURN; END IF;
 IF part.state<>'rendering' OR part.lease_token IS DISTINCT FROM p_lease OR part.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'BATCH_STALE_LEASE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=b.occasion AND "user"=part.lease_actor AND is_editor_order_view) THEN RAISE insufficient_privilege; END IF;
 IF p_pages<>cardinality(part.ticket_ids) THEN RAISE EXCEPTION 'BATCH_DOCUMENT_PAGE_COUNT'; END IF;
 UPDATE eshop.ticket_batch_document_parts SET state='ready',object_key=b.id::text||'/'||b.manifest_hash||'/'||part.part_key||'.pdf',
 content_digest=p_digest,byte_count=p_bytes,page_count=p_pages,lease_token=NULL,lease_expires_at=NULL,error_code=NULL WHERE id=p_part;
END $$;
CREATE OR REPLACE FUNCTION public.fail_ticket_batch_document_internal(p_batch uuid,p_part uuid,p_lease uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 UPDATE eshop.ticket_batches SET resource_error_code='RESOURCE_PREPARATION_FAILED',resource_lease_token=NULL,resource_lease_expires_at=NULL
 WHERE id=p_batch AND manifest_hash IS NULL AND resource_lease_token=p_lease;
 UPDATE eshop.ticket_batch_document_parts SET state='failed',error_code='RENDER_FAILED',lease_token=NULL,lease_expires_at=NULL
 WHERE batch_id=p_batch AND id=p_part AND lease_token=p_lease AND state='rendering';
END $$;
CREATE OR REPLACE FUNCTION public.get_ticket_batch_stored_document(p_ticket bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.ticket_batches; part eshop.ticket_batch_document_parts; oc bigint;
BEGIN
 SELECT occasion INTO oc FROM eshop.tickets WHERE id=p_ticket;
 IF auth.role()<>'service_role' AND (auth.uid() IS NULL OR public.get_is_editor_order_view_on_occasion(oc) IS NOT TRUE) THEN RAISE insufficient_privilege; END IF;
 SELECT b0.* INTO b FROM eshop.ticket_batches b0 JOIN eshop.ticket_batch_items i ON i.batch_id=b0.id WHERE i.ticket_id=p_ticket;
 IF b.id IS NULL THEN RETURN NULL; END IF;
 IF auth.role()<>'service_role' AND (auth.uid() IS NULL OR public.get_is_editor_order_view_on_occasion(b.occasion) IS NOT TRUE) THEN RAISE insufficient_privilege; END IF;
 SELECT * INTO part FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND kind='single' AND ticket_ids=ARRAY[p_ticket];
 IF part.state IS DISTINCT FROM 'ready' THEN RAISE EXCEPTION 'BATCH_PRINT_NOT_READY'; END IF;
 RETURN jsonb_build_object('objectKey',part.object_key,'digest',part.content_digest,'bytes',part.byte_count);
END $$;
REVOKE ALL ON FUNCTION public.claim_ticket_batch_document(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_ticket_batch_document(uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.complete_ticket_batch_resources_internal(uuid,uuid,jsonb,integer),
 public.complete_ticket_batch_document_internal(uuid,uuid,text,bigint,integer),public.fail_ticket_batch_document_internal(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_ticket_batch_resources_internal(uuid,uuid,jsonb,integer),
 public.complete_ticket_batch_document_internal(uuid,uuid,text,bigint,integer),public.fail_ticket_batch_document_internal(uuid,uuid,uuid) TO service_role;
REVOKE ALL ON FUNCTION public.get_ticket_batch_stored_document(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_ticket_batch_stored_document(bigint) TO authenticated,service_role;

-- Source: database/functions/users/import_users_from_tickets.sql
CREATE OR REPLACE FUNCTION public.import_ticket_profiles_internal_v1(p_occasion_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    ticket_record RECORD;
    v_global_before jsonb;
    order_data JSONB;
    user_email TEXT;
    v_sign_in_email TEXT;
    user_name TEXT;
    user_surname TEXT;
    user_sex TEXT;
    user_data JSONB;
    v_user_id UUID;
    v_organization_id BIGINT;
    field_element JSONB;
    field_key TEXT;

    field_info RECORD;
    field_value TEXT;
    v_text1 TEXT;
    v_text2 TEXT;
    v_birthDate TEXT;

    v_occasion_user_row public.occasion_users%ROWTYPE;
    new_email TEXT;

    -- Arrays to store results
    inserted_users JSONB[] := ARRAY[]::JSONB[];
    updated_users JSONB[] := ARRAY[]::JSONB[];
    deleted_users JSONB[] := ARRAY[]::JSONB[];

    storno_record RECORD;
    deleted_user_info RECORD;
    update_report_info RECORD;
BEGIN
    -- 1. Get the organization_id from the occasion
    SELECT organization INTO v_organization_id FROM public.occasions WHERE id = p_occasion_id;

    IF v_organization_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with id % not found or has no organization.', p_occasion_id;
    END IF;

    -- 2. Handle Storno (Canceled) Tickets
    FOR storno_record IN
        SELECT ou."user", ou.ticket
        FROM public.occasion_users ou
        JOIN eshop.tickets t ON ou.ticket = t.id
        WHERE ou.occasion = p_occasion_id
          AND ou.ticket IS NOT NULL
          AND t.state = 'storno'
    LOOP
        SELECT ui.email_readonly, ui.name, ui.surname
        INTO deleted_user_info
        FROM public.user_info ui
        WHERE ui.id = storno_record."user";

        PERFORM public.delete_occasion_user(storno_record."user", p_occasion_id);

        deleted_users := array_append(deleted_users,
            jsonb_build_object(
                'email', deleted_user_info.email_readonly,
                'name', deleted_user_info.name,
                'surname', deleted_user_info.surname,
                'ticket_id', storno_record.ticket
            )
        );
    END LOOP;

    -- 3. IMPORT & SYNC LOGIC
    FOR ticket_record IN
        SELECT DISTINCT ON (t.id)
            t.id as ticket_id,
            o.data as order_data,
            ou."user" as existing_occasion_user_id
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        LEFT JOIN public.occasion_users ou ON t.id = ou.ticket
        WHERE t.occasion = p_occasion_id
          AND t.state IN ('ordered', 'sent', 'used', 'paid')
          AND NOT EXISTS(SELECT 1 FROM eshop.ticket_batch_items i WHERE i.ticket_id=t.id)
        ORDER BY t.id, o.id DESC
    LOOP
        order_data := ticket_record.order_data;
        user_email := lower(trim(order_data->>'email'));
        user_name := order_data->>'name';
        user_surname := order_data->>'surname';
        user_sex := NULL;

        v_text1 := NULL;
        v_text2 := NULL;
        v_birthDate := NULL;

        -- Extract Form Fields (Generic loop, checking specifically for known titles)
        IF jsonb_typeof(order_data->'fields') = 'array' THEN
            FOR field_element IN SELECT * FROM jsonb_array_elements(order_data->'fields')
            LOOP
                field_key := (SELECT * FROM jsonb_object_keys(field_element));
                field_value := field_element->>field_key;

                SELECT ff.type, ff.title
                INTO field_info
                FROM public.form_fields ff
                WHERE ff.id = field_key::bigint;

                -- Basic mappings
                IF field_info.type = 'sex' THEN
                    user_sex := field_value;
                END IF;

--                -- Custom mappings (removed IF ID=36 check to make it generic for the feature)
--                CASE field_info.title
--                    WHEN 'Typ účastníka' THEN
--                        v_text1 := field_value;
--                    WHEN 'Přípravný tým' THEN
--                        v_text2 := field_value;
--                    WHEN 'Datum narození' THEN
--                        v_birthDate := field_value;
--                    ELSE
--                        -- Do nothing
--                END CASE;
            END LOOP;
        END IF;

        -- ========================================================
        -- CASE A: EXISTING OCCASION USER -> UPDATE BY ID
        -- ========================================================
        IF ticket_record.existing_occasion_user_id IS NOT NULL THEN
            DECLARE
                current_ou_data JSONB;
                update_payload JSONB := '{}'::jsonb;
                target_uuid UUID := ticket_record.existing_occasion_user_id; -- STRICT ID DEPENDENCY
            BEGIN
                SELECT ui.email_readonly
                  INTO v_sign_in_email
                  FROM public.user_info ui
                 WHERE ui.id = target_uuid;

                -- Get current occasion data
                SELECT data INTO current_ou_data
                FROM public.occasion_users
                WHERE "user" = target_uuid AND occasion = p_occasion_id;

                -- Build payload comparing Order Data vs Current DB Data
                IF v_sign_in_email IS NOT NULL AND COALESCE(current_ou_data->>'email', 'NULL_FLAG') != v_sign_in_email THEN
                    update_payload := update_payload || jsonb_build_object('email', v_sign_in_email);
                END IF;
                IF user_name IS NOT NULL AND COALESCE(current_ou_data->>'name', 'NULL_FLAG') != user_name THEN
                    update_payload := update_payload || jsonb_build_object('name', user_name);
                END IF;
                IF user_surname IS NOT NULL AND COALESCE(current_ou_data->>'surname', 'NULL_FLAG') != user_surname THEN
                    update_payload := update_payload || jsonb_build_object('surname', user_surname);
                END IF;
                IF user_sex IS NOT NULL AND COALESCE(current_ou_data->>'sex', 'NULL_FLAG') != user_sex THEN
                    update_payload := update_payload || jsonb_build_object('sex', user_sex);
                END IF;
                -- Custom fields
--                IF v_text1 IS NOT NULL AND COALESCE(current_ou_data->>'text1', 'NULL_FLAG') != v_text1 THEN
--                    update_payload := update_payload || jsonb_build_object('text1', v_text1);
--                END IF;
--                IF v_text2 IS NOT NULL AND COALESCE(current_ou_data->>'text2', 'NULL_FLAG') != v_text2 THEN
--                    update_payload := update_payload || jsonb_build_object('text2', v_text2);
--                END IF;
--                IF v_birthDate IS NOT NULL AND COALESCE(current_ou_data->>'birthDate', 'NULL_FLAG') != v_birthDate THEN
--                    update_payload := update_payload || jsonb_build_object('birthDate', v_birthDate);
--                END IF;

                -- Perform Updates if needed
                IF update_payload != '{}'::jsonb THEN
                    -- 1. Update Occasion Specific Data
                    UPDATE public.occasion_users
                    SET data = data || update_payload
                    WHERE "user" = target_uuid
                      AND occasion = p_occasion_id;

                    -- 2. Update Global User Info (Sync core fields)
                    
                    SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=target_uuid FOR UPDATE;
UPDATE public.user_info
                    SET
                        name = COALESCE(update_payload->>'name', name),
                        surname = COALESCE(update_payload->>'surname', surname),
                        sex = COALESCE(update_payload->>'sex', sex)
                    WHERE id = target_uuid;
                    PERFORM public.publish_user_profile_change_internal_v1(target_uuid,p_occasion_id,v_global_before);

                    -- Logging
                    SELECT ui.email_readonly, ui.name, ui.surname
                    INTO update_report_info
                    FROM public.user_info ui
                    WHERE ui.id = target_uuid;

                    updated_users := array_append(updated_users,
                        jsonb_build_object(
                            'id', target_uuid, -- Return ID for safety
                            'email', update_report_info.email_readonly,
                            'name', update_report_info.name,
                            'surname', update_report_info.surname,
                            'reason', 'data_sync',
                            'changes', update_payload
                        )
                    );
                END IF;
            END;

        -- ========================================================
        -- CASE B: NO LINKED USER -> CREATE OR LINK (FALLBACK TO EMAIL)
        -- ========================================================
        ELSE
            -- 1. Check if user exists globally by email
            SELECT id INTO v_user_id
            FROM public.user_info
            WHERE email_readonly = user_email AND organization = v_organization_id;

            IF v_user_id IS NOT NULL THEN
                -- USER EXISTS GLOBALLY
                SELECT * INTO v_occasion_user_row
                FROM public.occasion_users
                WHERE "user" = v_user_id AND occasion = p_occasion_id;

                IF v_occasion_user_row."user" IS NOT NULL AND v_occasion_user_row.ticket IS NOT NULL THEN
                    -- User exists on occasion AND has a ticket -> DUPLICATE EMAIL Conflict
                    -- Create new user with +suffix
                    new_email := public.allocate_user_sign_in_email(
                        v_organization_id, user_email
                    );

                    user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', new_email, 'sex', user_sex);
--                    IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                    IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                    IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                    v_user_id := create_user_in_organization_with_data_pure(
                        v_organization_id, new_email, user_email,
                        gen_random_uuid()::text, user_data
                    );
                    PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                    UPDATE public.occasion_users SET ticket = ticket_record.ticket_id WHERE "user" = v_user_id AND occasion = p_occasion_id;

                    inserted_users := array_append(inserted_users, jsonb_build_object('id', v_user_id, 'email', new_email, 'name', user_name, 'surname', user_surname));
                ELSE
                    -- LINK EXISTING USER (User exists, but no ticket on this occasion)

                    user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', user_email, 'sex', user_sex);
--                    IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                    IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                    IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                    -- Update Global Info
                    
                    SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user_id FOR UPDATE;
UPDATE public.user_info
                    SET
                        name = user_name,
                        surname = user_surname,
                        sex = user_sex,
                        data = COALESCE(user_info.data, '{}'::jsonb) || user_data
                    WHERE id = v_user_id;
                    PERFORM public.publish_user_profile_change_internal_v1(v_user_id,p_occasion_id,v_global_before);

                    IF v_occasion_user_row."user" IS NULL THEN
                        -- Link to occasion
                        PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                    END IF;

                    -- Update Occasion Data & Ticket
                    UPDATE public.occasion_users
                    SET
                        data = COALESCE(occasion_users.data, '{}'::jsonb) || user_data,
                        ticket = ticket_record.ticket_id
                    WHERE "user" = v_user_id AND occasion = p_occasion_id;

                    updated_users := array_append(updated_users, jsonb_build_object('id', v_user_id, 'email', user_email, 'name', user_name, 'surname', user_surname, 'reason', 'initial_import_link'));
                END IF;
            ELSE
                -- NEW USER CREATION
                user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', user_email, 'sex', user_sex);
--                IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                v_user_id := create_user_in_organization_with_data_pure(
                    v_organization_id, user_email, user_email,
                    gen_random_uuid()::text, user_data
                );
                PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                UPDATE public.occasion_users SET ticket = ticket_record.ticket_id WHERE "user" = v_user_id AND occasion = p_occasion_id;

                inserted_users := array_append(inserted_users, jsonb_build_object('id', v_user_id, 'email', user_email, 'name', user_name, 'surname', user_surname));
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'inserted', to_jsonb(inserted_users),
        'updated', to_jsonb(updated_users),
        'deleted', to_jsonb(deleted_users)
    );
END;
$function$
;

REVOKE ALL ON FUNCTION public.import_ticket_profiles_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.import_users_from_tickets(bigint) FROM PUBLIC,anon,authenticated,service_role;

